-- EXEC.md EXEC-1018B Fase 2 (E6, E9 d/e/f, E1; user "Jalankan.", 2026-10-16): the tool contracts the code now offers.
-- export_result exports the rows a data request delivered (data_request, need_id), a supporting
-- table (working tables kept 30 days, rebuilt from the stored code after that and exported only on
-- an exact match), and adds input sheets to an XLSX of a result (E1, E9). complete_analysis says a
-- name emitted again replaces the earlier output (E6).
-- Inactive like every market-ai-orc row; input schema and purpose from the code, every other column copied from the
-- previous version.
-- GENERATED by scripts/generate_tool_catalog_migration.py; market-ai-orc tests/test_data_need_tool.py fails on
-- drift. Do not edit by hand.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('export_result', 'v5'), ('complete_analysis', 'orc-v3'))) <> 2 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''export_result'', ''v5''), (''complete_analysis'', ''orc-v3'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'export_result' AND version = 'v6') OR (tool_name = 'complete_analysis' AND version = 'orc-v4')) THEN
        RAISE EXCEPTION 'The the data behind a result, replaced outputs tool versions are already registered';
    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"design":"EXEC.md EXEC-1018B","export_result":"input sheets at most 200,000 rows together; a supporting table kept 30 days","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('export_result', 'v5', 'v6', '{"additionalProperties":false,"properties":{"column_labels":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"The column''s name in the output.","type":"string"},"label":{"description":"Its title in the user''s language.","type":"string"}},"required":["column","label"],"type":"object"},"type":"array"},{"type":"null"}],"description":"XLSX: the title the reader sees for each column, in the user''s language; a column not named keeps its name made readable."},"data_request":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A data request of an approved need in the data record (data_request_1_A): the rows it delivered. Limits: matching ^[A-Za-z0-9_]{1,80}$."},"evidence_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A checked claim''s evidence rows. Limits: matching ^evd_[0-9a-f]{24}$."},"format":{"enum":["CSV","XLSX","PARQUET"],"type":"string"},"include_definition":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"XLSX: a sheet with the output''s definition (default true)."},"include_lineage":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"XLSX: a sheet with where the data came from (default true)."},"need_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"With data_request: the need it belongs to (default: the newest). Limits: matching ^need_[0-9a-f]{24}$."},"output_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Limits: matching ^out_[0-9a-f]{24}$."},"ref":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The output''s value reference. Limits: matching ^(out\\.)?o[1-9][0-9]{0,3}$."},"source_columns":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"The column''s name in the output.","type":"string"},"source_column":{"description":"The source table''s column it was copied from, exactly as the catalog names it (for example Date for trading_date).","type":"string"}},"required":["column","source_column"],"type":"object"},"type":"array"},{"type":"null"}],"description":"XLSX: the source table''s column of each column copied from it (renamed or not); a computed column is not listed."}},"required":["ref","output_id","evidence_id","data_request","need_id","format","include_definition","include_lineage","column_labels","source_columns"],"type":"object"}',
     'Write an output as a file the user downloads (CSV, XLSX with definition and lineage sheets, or PARQUET), at most 20 MB. Give ref (out.o3), output_id, or evidence_id (a checked claim''s evidence rows). Returns export_id, file name, size and format only; the answer names the file, the user downloads it. For XLSX give column_labels: the title of each column in the user''s language, as the reader should see it, and source_columns: for each column copied from a source table (renamed or not), that table''s column name; never for a computed column. The backend adds to the XLSX definition sheet what one row is and how complete each group is against the source table. The data behind a result (E9): data_request (with need_id when several needs share it) exports the rows a data request of an approved need delivered, as listed in the data record ([data_request_1_A]): the approved ranges, no code and no session needed; a ref of a supporting table (the data record''s Supporting tables: working tables and steps) exports that table. data_status says where the file came from: STORED (kept copy), REBUILT (the same approved need extracted again, or after its 30 days a supporting table rebuilt by running the stored code again; a rebuilt supporting table is exported only when it matches the original exactly), EXPIRED_NOT_REBUILDABLE (refused, with the reason: say so and offer to compute it again). same_rows_as_original false means the source data changed since: say so. An XLSX of a result also gets one sheet per input whose rows the file does not span (warm-up and base rows included); inputs lists each one (INCLUDED, COVERED, NOT_INCLUDED with the reason).'),
    ('complete_analysis', 'orc-v3', 'orc-v4', '{"additionalProperties":false,"properties":{"session_id":{"description":"Limits: matching ^sess_[0-9a-f]{24}$.","type":"string"}},"required":["session_id"],"type":"object"}',
     'Finish the analysis of a session. The backend builds the ExecutionManifest and runs the Coverage Validator: every approved data request and range must have been delivered as approved and read in full through the saniti helpers in a successful execution, with at least one output. Returns final_status (data_coverage PASS/FAIL, sandbox_execution, calculation_validation NOT_PERFORMED, evidence_label, warnings, claims_allowed, claims_forbidden) and, on PASS, the released outputs with their content (JSON outputs and the first table rows). Only released outputs may be cited in the answer; disclose the warnings. On FAIL follow next_action: RUN_PYTHON (read what was not processed, then complete again), REVISE_DATA_NEED_SPEC, or REPORT_LIMITATION. The backend does not recalculate your formulas: never say a calculation was independently verified. An output name emitted again by a later run replaces the earlier output of that name: only the newest is released, and an earlier address is refused with the new one (replaced_outputs); give different results different names. Exception: the tables of saniti.event_study are recomputed by the backend from their declaration. final_status.event_studies lists each study (PASS, FAIL with CALCULATION_MISMATCH, INVALID) and verified_output_ids the matched tables; calculation_validation is then PARTIAL (other outputs exist) or FORMULA_AND_STATISTICS_VERIFIED. Only those tables may be called independently recalculated; a FAIL makes the completion INCOMPLETE: run the event study again and complete again. The tables of saniti.backtest are re-run by the backend on the bundle prices from their signal dates: final_status.backtests lists each (PASS, FAIL with CALCULATION_MISMATCH, INVALID); the signals themselves are the code''s and are not recomputed.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'export_result' AND version = 'v6') OR (tool_name = 'complete_analysis' AND version = 'orc-v4'))) <> 2 THEN
        RAISE EXCEPTION 'The the data behind a result, replaced outputs tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'export_result' AND version = 'v6' AND input_schema::text LIKE '%data_request%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'complete_analysis' AND version = 'orc-v4' AND purpose::text LIKE '%replaced_outputs%') THEN
        RAISE EXCEPTION 'The the data behind a result, replaced outputs contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
